SELECT *
FROM admin


        is_deleted = #{dto.isDeleted}


        AND roleName = #{dto.roleName}


        AND roleName LIKE CONCAT('%',#{dto.roleNameLike},'%')


        AND roleCode = #{roleCode}


        AND description LIKE CONCAT('%',#{description},'%')


        AND status = #{dto.status}


        AND create_time >= #{dto.createTimeStart}


        AND create_time <= #{dto.createTimeEnd}


ORDER BY id ASC
LIMIT #{offset}, #{dto.size}

